uint32_t read32(const Bytes&b,size_t p){if(p+4>b.size())throw std::runtime_error("Truncated WAV");uint32_t v;std::memcpy(&v,b.data()+p,4);return v;}
struct Sample{std::vector<float>pcm;unsigned rate=44100;double cursor=0;float rpm=4000;};
Sample wave(const Resources&r,const std::string&name){auto b=r.read("sound/"+name);if(b.size()<12||read32(b,0)!=0x46464952||read32(b,8)!=0x45564157)throw std::runtime_error("WAV header");unsigned channels=0,bits=0,format=0;size_t offset=0,length=0;Sample s;for(size_t p=12;p+8<=b.size();){uint32_t n=read32(b,p+4);if(n>b.size()-p-8)throw std::runtime_error("WAV chunk span");if(read32(b,p)==0x20746d66&&n>=16){format=b[p+8]+256*b[p+9];channels=b[p+10]+256*b[p+11];s.rate=read32(b,p+12);bits=b[p+22]+256*b[p+23];}if(read32(b,p)==0x61746164){offset=p+8;length=n;}p+=8+size_t(n)+(n&1);}if(format!=1||(channels!=1&&channels!=2)||(bits!=8&&bits!=16)||!length||s.rate<8000||s.rate>192000)throw std::runtime_error("Only PCM 8/16-bit native engine WAV supported");size_t stride=channels*bits/8;for(size_t p=offset;p+stride<=offset+length;p+=stride){float v=0;for(unsigned c=0;c<channels;c++){if(bits==8)v+=(int(b[p+c])-128)/128.f;else{int16_t x;std::memcpy(&x,b.data()+p+c*2,2);v+=x/32768.f;}}s.pcm.push_back(v/channels);}if(s.pcm.empty())throw std::runtime_error("Empty WAV");return s;}
float play(Sample&s,float rpm){double cursor=s.cursor;size_t a=size_t(cursor)%s.pcm.size(),b=(a+1)%s.pcm.size();float v=s.pcm[a]+(s.pcm[b]-s.pcm[a])*float(cursor-std::floor(cursor));s.cursor=std::fmod(cursor+std::clamp(rpm/s.rpm,.25f,3.f)*double(s.rate)/44100.,double(s.pcm.size()));return v;}
