struct Audio::Impl {
 std::unique_ptr<NitroAudioMixer>nitro;Json nitro_report;bool nitro_active=false;std::unique_ptr<CollisionAudioMixer>collision;Json collision_report;std::vector<CollisionEvent>pending_collisions;double queued_time=0;uint64_t queued_collision=0,queued_generation=0;Vec listener{};std::unique_ptr<SurfaceAudioMixer>surface;Json surface_report;std::array<WheelContact,4>contacts{};double surface_time=0;uint64_t surface_generation=0;std::array<Sample,7>samples;std::array<float,4>xf_lo{},xf_hi{},xf_gain{};Json config,report;HWAVEOUT out=nullptr;std::thread worker;std::atomic<bool>stop{false};std::mutex mutex;float target_rpm=1000,throttle=0,volume=.55f;bool enabled=false,surfaces_enabled=false;std::string error;
 struct Buffer{std::array<int16_t,2048>pcm{};WAVEHDR hdr{};};std::array<Buffer,4>buffers;
 Impl(const Resources&r,int id,const Geometry&geometry,const std::string&stage){try{nitro=std::make_unique<NitroAudioMixer>(r,load_nitro_audio_config(r));nitro_report=nitro->diagnostics();}catch(const std::exception&e){nitro_report={{"error",e.what()}};}try{collision=std::make_unique<CollisionAudioMixer>(r,load_collision_audio_config(r));collision_report=collision->diagnostics();}catch(const std::exception&e){collision_report={{"error",e.what()}};}try{surface=std::make_unique<SurfaceAudioMixer>(r,load_surface_audio_config(r,load_wheel_effect_config(r,geometry,stage)));surface_report=surface->diagnostics();}catch(const std::exception&e){surface_report={{"error",e.what()}};}try{const int sample_id=id>=17&&id<=20?3:id;config=bed_file(r,"sound/engine_"+std::to_string(sample_id)+"_0.bed");for(int i=0;i<4;i++){auto f=config.at("RPMXFader").at(std::to_string(i+1));xf_lo[i]=f.value("Min",0.f);xf_hi[i]=f.value("Max",10000.f);xf_gain[i]=f.value("Gain",1.f);}samples[0]=wave(r,config.at("IdleSample").at("Wave"));samples[0].rpm=config["IdleSample"].value("RPM",1000.f);const char*keys[]={"OnLow","OnMid","OnHigh","OffLow","OffMid","OffHigh"};for(int i=0;i<6;i++){samples[i+1]=wave(r,config["Samples"].at(keys[i]));samples[i+1].rpm=config["Samples"].value(std::string(keys[i])+"_RPM",4000.f);}WAVEFORMATEX fmt{};fmt.wFormatTag=WAVE_FORMAT_PCM;fmt.nChannels=2;fmt.nSamplesPerSec=44100;fmt.wBitsPerSample=16;fmt.nBlockAlign=4;fmt.nAvgBytesPerSec=176400;if(waveOutOpen(&out,WAVE_MAPPER,&fmt,0,0,CALLBACK_NULL)!=MMSYSERR_NOERROR)throw std::runtime_error("waveOutOpen unavailable");for(auto&b:buffers){b.hdr.lpData=(LPSTR)b.pcm.data();b.hdr.dwBufferLength=sizeof b.pcm;if(waveOutPrepareHeader(out,&b.hdr,sizeof b.hdr)!=MMSYSERR_NOERROR)throw std::runtime_error("waveOutPrepareHeader failed");}worker=std::thread([this]{mix();});}catch(const std::exception&e){error=e.what();if(out){waveOutReset(out);for(auto&b:buffers)if(b.hdr.dwFlags&WHDR_PREPARED)waveOutUnprepareHeader(out,&b.hdr,sizeof b.hdr);waveOutClose(out);out=nullptr;}}}
 ~Impl(){stop=true;if(worker.joinable())worker.join();if(out){waveOutReset(out);for(auto&b:buffers)waveOutUnprepareHeader(out,&b.hdr,sizeof b.hdr);waveOutClose(out);}}
 void mix(){bool started=false;float rpm=1000,load=0,gain=0;float rt=config.value("RPMSmooth",.12f),tt=config.value("ThrottleSmooth",.08f);while(!stop){bool wrote=false;for(auto&b:buffers){if((b.hdr.dwFlags&WHDR_INQUEUE))continue;float tr,th,vol;bool on,surface_on,nitro_on;std::array<WheelContact,4>feet;double clock;uint64_t generation;std::vector<CollisionEvent>events;Vec ear;{std::lock_guard<std::mutex>lock(mutex);tr=target_rpm;th=throttle;vol=volume;on=enabled;surface_on=surfaces_enabled;nitro_on=nitro_active;feet=contacts;clock=surface_time;generation=surface_generation;events.swap(pending_collisions);ear=listener;}if(!started&&!on)continue;started=true;if(nitro)nitro->update(nitro_on,on&&surface_on,clock,generation);if(collision)collision->update(events,clock,generation,on,ear);if(surface)surface->update(feet,clock,generation,on&&surface_on);for(size_t i=0;i<b.pcm.size();i+=2){rpm+=(tr-rpm)*(1-std::exp(-1.f/(44100*std::max(.01f,rt))));load+=(th-load)*(1-std::exp(-1.f/(44100*std::max(.01f,tt))));gain+=((on?vol:0)-gain)*.001f;float weights[4]{},sum=0;for(int n=0;n<4;n++){float lo=xf_lo[n],hi=xf_hi[n];float center=(lo+hi)*.5f;float w=std::max(0.f,1-std::abs(rpm-center)/std::max(1.f,(hi-lo)*.5f));weights[n]=w*xf_gain[n];sum+=weights[n];}if(sum<1e-5f){weights[rpm<3000?0:3]=1;sum=1;}float value=play(samples[0],rpm)*weights[0];for(int n=0;n<3;n++)value+=(play(samples[n+1],rpm)*load+play(samples[n+4],rpm)*(1-load))*weights[n+1];int16_t outv=int16_t(std::tanh((value/sum+(surface?surface->frame()*.45f:0)+(collision?collision->frame()*.75f:0)+(nitro?nitro->frame():0))*gain*.75f)*30000);b.pcm[i]=b.pcm[i+1]=outv;}if(surface||collision||nitro){std::lock_guard<std::mutex>lock(mutex);if(nitro)nitro_report=nitro->diagnostics();if(surface)surface_report=surface->diagnostics();if(collision)collision_report=collision->diagnostics();}if(waveOutWrite(out,&b.hdr,sizeof b.hdr)!=MMSYSERR_NOERROR){stop=true;break;}wrote=true;}if(!wrote)Sleep(2);}}
};
Audio::Audio(const Resources&r,int id,const Geometry&g,const std::string&stage):p_(std::make_unique<Impl>(r,id,g,stage)){}Audio::~Audio()=default;void Audio::update(const State&s,const Input&i,float v,bool enabled,bool surfaces_enabled){std::lock_guard<std::mutex>lock(p_->mutex);if(p_->queued_generation!=s.recovery_generation||s.time+1e-6<p_->queued_time){p_->queued_generation=s.recovery_generation;p_->queued_collision=0;p_->pending_collisions.clear();}p_->queued_time=s.time;if(!enabled)p_->pending_collisions.clear();if(s.collision_events)for(const auto&e:*s.collision_events)if(e.id>p_->queued_collision){if(enabled){if(p_->pending_collisions.size()==256)p_->pending_collisions.erase(p_->pending_collisions.begin());p_->pending_collisions.push_back(e);}p_->queued_collision=e.id;}p_->listener=s.driver_ejected?point(s.driver,{}):point(s.car,{});p_->contacts=s.wheel_contacts;p_->surface_time=s.time;p_->surface_generation=s.recovery_generation;p_->target_rpm=s.rpm;p_->throttle=std::abs(i.throttle);p_->volume=std::clamp(v,0.f,1.f);p_->nitro_active=s.nitro_active;p_->enabled=enabled;p_->surfaces_enabled=surfaces_enabled;}Json Audio::diagnostics()const{std::lock_guard<std::mutex>lock(p_->mutex);return{{"backend","waveOut PCM; independent bounded mixer thread"},{"active",p_->out!=nullptr&&!p_->stop},{"error",p_->error},{"nitro",p_->nitro_report},{"surfaces",p_->surface_report},{"collisions",p_->collision_report},{"limits","Native engine/surface/water/impact/nitro PCM WAVs; adapted mono mix, distance attenuated impacts, no occlusion or shift system"}};}
